"""
Construye un dataset con columnas acumuladas de Answer.
Cada refresh inserta la columna 'Answer' (la más reciente) justo después
de 'Description' y desplaza las previas ('Answer', 'Answer_1', ...) a la derecha.
El dataset acumulado se persiste en self.custom.accumulatedDS.
"""

# --- 1) Trae preguntas (Description, ID) en el orden requerido ---
db = value['db']
query = '''SELECT Description,ID 
	FROM papo.dbo.papoitem
	WHERE PapoID=?
	ORDER BY 
	  CASE RegisterTypeID
	    WHEN 7 THEN 1
	    WHEN 3 THEN 2
	    WHEN 1 THEN 3
	    WHEN 2 THEN 4
	    ELSE 5
	  END;'''
params = [1]
ds_papoItems = system.db.runPrepQuery(query, params, db)

# --- 2) Función auxiliar: JSON -> dict {papoitemID: answer} ---
def _safeJsonDecode(s):
	try:
		return system.util.jsonDecode(s)
	except:
		if isinstance(s, basestring) and len(s) >= 2 and s[0] == '"' and s[-1] == '"':
			try:
				unescaped = s[1:-1].replace(r'\"', '"')
				return system.util.jsonDecode(unescaped)
			except:
				return []
		return []

# --- 3) Trae JSON de respuestas ---
query = '''
	SELECT DataAnswer
	FROM registerhistory
	WHERE RegisterTypeID=? AND PapoID=? AND NodeID=?;
'''
params = [3, 1, 6]
ds_table = system.db.runPrepQuery(query, params, db)
jsonStr = ds_table.getValueAt(0, 0) if ds_table.getRowCount() > 0 else '[]'
parsed = _safeJsonDecode(jsonStr) or []

jsonMap = {}
for obj in parsed:
	try:
		pid = int(obj.get("papoitemID"))
		jsonMap[pid] = obj.get("answer", None)
	except:
		continue

# --- 4) Arma la columna "Answer" actual en orden de ds_papoItems ---
descCol = "Description" if "Description" in ds_papoItems.getColumnNames() else "Descripcion"
cur_rows_by_desc = {}
cur_rows = []
for r in range(ds_papoItems.getRowCount()):
	desc = ds_papoItems.getValueAt(r, descCol)
	idVal = ds_papoItems.getValueAt(r, "ID")
	try:
		idInt = int(idVal)
	except:
		idInt = None
	answer = jsonMap.get(idInt, None)
	cur_rows.append([desc, answer])
	cur_rows_by_desc[desc] = answer

cur_ds = system.dataset.toDataSet(["Description", "Answer"], cur_rows)

# --- 5) Recupera el acumulado previo (si existe) ---
try:
	prev_ds = self.custom.accumulatedDS
except:
	prev_ds = None

# Si no hay acumulado previo, inicializa con el dataset actual
if prev_ds is None or prev_ds.getRowCount() == 0:
	try:
		self.custom.accumulatedDS = cur_ds
	except:
		pass
	return cur_ds

# --- 6) Construye headers con bump de nombres de Answer previos ---
def _bump_answer_headers(headers):
	# headers[0] es "Description"; para el resto:
	out = []
	for h in headers[1:]:
		if h == "Answer":
			out.append("Answer_1")
		elif isinstance(h, basestring) and h.startswith("Answer_"):
			try:
				n = int(h.split("_", 1)[1])
				out.append("Answer_%d" % (n + 1))
			except:
				out.append(h + "_old")
		else:
			out.append(h)
	return out

prev_headers = list(prev_ds.getColumnNames())
bumped_prev = _bump_answer_headers(prev_headers)
new_headers = ["Description", "Answer"] + bumped_prev  # inserta Answer más reciente

# --- 7) Mapa de filas previas por Description ---
prev_index_by_desc = {}
if "Description" in prev_headers:
	desc_idx_prev = list(prev_headers).index("Description")
	for r in range(prev_ds.getRowCount()):
		dv = prev_ds.getValueAt(r, desc_idx_prev)
		prev_index_by_desc[dv] = r

# --- 8) Fusiona por Description: nueva Answer + columnas previas bumpadas ---
new_rows = []
for r in range(ds_papoItems.getRowCount()):
	desc = ds_papoItems.getValueAt(r, descCol)
	current_answer = cur_rows_by_desc.get(desc, None)

	row = [desc, current_answer]

	if desc in prev_index_by_desc:
		rp = prev_index_by_desc[desc]
		# Toma todas las columnas previas a partir de la 1 (excluye Description)
		for c in range(1, prev_ds.getColumnCount()):
			row.append(prev_ds.getValueAt(rp, c))
	else:
		# Si la fila no existía antes, llena vacíos para las columnas previas
		row.extend([None] * len(bumped_prev))

	new_rows.append(row)

out_ds = system.dataset.toDataSet(new_headers, new_rows)

# --- 9) Persiste el acumulado y retorna ---
try:
	self.custom.accumulatedDS = out_ds
except:
	pass

return out_ds

